import{_ as o,l,o as e,c as s,v as t,p as n,x as i,d as h,i as p,S as A}from"./chunks/framework.InCnrqk-.js";const C=JSON.parse('{"title":"刻蚀偏置与 CDU","description":"","frontmatter":{"title":"刻蚀偏置与 CDU","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/cdu-etch-bias.md","filePath":"litho/cdu-etch-bias.md","lastUpdated":1789023840000}'),E={name:"litho/cdu-etch-bias.md"};function d(D,a,c,I,m,f){const r=l("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="刻蚀偏置与-cdu" tabindex="-1">刻蚀偏置与 CDU <a class="header-anchor" href="#刻蚀偏置与-cdu" aria-label="Permalink to &quot;刻蚀偏置与 CDU&quot;">​</a></h1><div class="epigraph"><p>显影后的 CD 图还不是器件上的图。刻蚀把 ADI 的均值和指纹改写成 AEI：偏置可以修均匀性，也可以把热点放大。</p><footer>—— 据 Levinson 对显影后 / 刻蚀后计量与刻蚀偏置的产线讨论整理</footer></div><p><a href="/litho/hotspot-pv">上一课</a>把签核停在过程变化下的轮廓包络，默认还在胶上。缺口是转印：<a href="/litho/litho-process-flow">工艺流程</a>的最后一段把浮雕交给干法，横向侵蚀、微负载与深宽比依赖会让 CD 整表搬家。<a href="/litho/cdu-uniformity">CDU</a> 若只报 ADI，产品电学认的是 AEI。本课钉刻蚀偏置。浸没水膜如何维持，从下一课程的 <a href="/litho/arf-immersion">ArF 浸没</a> 架构另起，不在这里灌水。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>ADI（after develop inspect）是胶上 CD；AEI（after etch inspect）是硬掩模或衬底上 CD。偏置 \\(\\mathrm{AEI}-\\mathrm{ADI}\\) 随图形密度、节距、局部开孔率和深宽比变，不是一个全局常数。FEM 在胶上很大的窗，刻蚀后可以因负载把密线修细、孤立线修粗，重叠窗改形。热点的 PV-band 在胶上刚合格，刻蚀风一吹，桥连或断开改边。产品规格若写的是电学或 AEI，胶上窗只是中间量。</p><p>缺口因此是把 CDU 声明成哪一段的空间图，并承认刻蚀是一层空间滤波器，不是「把胶轮廓向下复印」。</p><h3 id="偏置可以改善也可以破坏均匀性" tabindex="-1">偏置可以改善也可以破坏均匀性 <a class="header-anchor" href="#偏置可以改善也可以破坏均匀性" aria-label="Permalink to &quot;偏置可以改善也可以破坏均匀性&quot;">​</a></h3><p>各向同性的过刻把所有线瘦一截，均值移动，相对 CDU 有时看起来更好（小图形被吃掉的比例不同则相反）。微负载让密区刻得慢、疏区刻得快，场内密度图变成新的 CDU 指纹，光刻剂量 mapper 补不平。Levinson 把光刻控制与刻蚀控制分成两段计量，原因在此。</p><p><span class="marginnote">报 CDU 必须写 ADI 还是 AEI。把胶上 3σ 和刻蚀后 3σ 排在同一张「进步」表里，是把两段工艺当成一次测量。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>成对计量：同一垫先 ADI 后 AEI（或相邻片短环），画偏置对节距、对密度。OPC / 刻蚀邻近修正用这张表，而不是假定偏置为零。控制环：光刻管 ADI 均值与光学指纹；刻蚀管负载与腔体漂移。把 AEI 漂移全部打回扫描机剂量，短期能扳均值，侧壁和深度会坏。</p><p>腔体换件或换气体之后，偏置表要重测，旧 OPC 邻近修正会过期。</p><p>热点验证若签核在胶上，量产失效在刻蚀后，要补 AEI SEM。金属氧化物胶自身硬掩模改变偏置曲线，不能把 CAR 的蚀刻表搬过去——<a href="/litho/euv-resist">euv-resist</a> 的选择比差在这里兑现。</p><h3 id="与-fem-的第二张窗" tabindex="-1">与 FEM 的第二张窗 <a class="header-anchor" href="#与-fem-的第二张窗" aria-label="Permalink to &quot;与 FEM 的第二张窗&quot;">​</a></h3><p>有的层以 AEI 规格签核，FEM 就要打到刻蚀后，或胶上 FEM 加一张校准过的偏置模型。模型未校准时空心加密，窗口面积不可信。禁戒节距在刻蚀后可能移动：光学禁戒加上负载，交集更瘦。</p>',15)),(e(),n(A,null,{default:i(()=>[p(r,{id:"mermaid-43",class:"mermaid",graph:"flowchart%20TD%0A%20%20ADI%5B%22ADI%20CDU%20%2F%20%E7%83%AD%E7%82%B9%22%5D%20--%3E%20ET%5B%22%E5%B9%B2%E6%B3%95%E5%88%BB%E8%9A%80%22%5D%0A%20%20ET%20--%3E%20BIAS%5B%22%E5%81%8F%E7%BD%AE%20%3D%20AEI%20-%20ADI%22%5D%0A%20%20LOAD%5B%22%E5%AF%86%E5%BA%A6%20%2F%20%E6%B7%B1%E5%AE%BD%E6%AF%94%E8%B4%9F%E8%BD%BD%22%5D%20--%3E%20BIAS%0A%20%20BIAS%20--%3E%20AEI%5B%22AEI%20CDU%20%2F%20%E7%94%B5%E5%AD%A6%22%5D%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[h(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>反应离子刻蚀的横向侵蚀与离子角度、聚合物沉积有关。开口大处反应剂足，开口小处耗尽，这就是微负载。深槽底部离子到达差，出现深宽比依赖，底 CD 与顶 CD 分家——OCD / 穆勒量的平均剖面在 AEI 上更关键，SEM 俯视会撒谎。光刻场内指纹若与密度图同相，刻蚀会放大；反相则部分抵消。抵消是运气，不是控制策略。</p><p>套刻标记的不对称往往在这一段生成：风把一侧侧壁打斜，DBO/IBO 偏置上升。计量课序把 CD 与 overlay 分开写，根子常在同一刻蚀风。</p><p><span class="marginnote">自对准双重的 spacer 偏置是另一张表：芯轴 CD 的 ADI 误差进入成对线的不对称。不要用单层 LELE 的 AEI–ADI 去解释 SADP。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写某腔体的未公开选择比，也不把 ALE / 原子层刻蚀当成已经取消偏置——<a href="/litho/ald-ale">ALD/ALE</a> 是另一课的纵向控制，横向负载仍在。计量课序到此：窗口、矩阵、均匀性、SEM/OCD、套刻链、flare、热点、刻蚀后 CDU 都已点名。后课默认：产品 CD 规格要写 ADI 或 AEI；只优化胶上窗是半截课。</p><p>浸没缺陷与面涂不在本课。下一课程从水作介质抬 NA 讲起，流体卫生另算。</p><p><span class="marginnote">电学 CD 还可能与 AEI SEM 再差一截（掺杂、硅损失）。AEI 仍是光刻–刻蚀链的合同界面，不是器件终点。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>刻蚀偏置把 ADI 的均值与指纹改写成 AEI，密度和深宽比是变量。</li><li>CDU 必须声明显影后还是刻蚀后；两段 3σ 不可混表。</li><li>剂量补偿补不平微负载；热点要以 AEI 再验。</li><li>标记不对称常在此段生成，套刻偏置与 CD 偏置同源。</li><li>出处：Levinson, <em>Principles of Lithography</em>；Mack 对图形转印链的分段。</li></ul>',10))])}const _=o(E,[["render",d]]);export{C as __pageData,_ as default};
